-- Dev-only seed (profile `local`, S-150): every seeded persona who can sign in gets a reusable authenticator key and ten
-- backup codes, so local testing never runs out of codes and needs no SMS. The list, the keys and the codes are
-- scripts/dev/personas.json (make creds prints each persona's current code; scripts/dev/personas.test.mjs checks this
-- file against it). Keys are dev-only base32 strings (NORTHLINE<NAME>DEVTOTPSECRET…), encrypted like V101's with the
-- local-only northline.auth.totp-key (server/auth/src/main/resources/application-local.yml) under key id v1 — never
-- valid anywhere else; db/seed-dev runs only under the local profile (DevSeedGuard, DbTool, not in the images).
-- Ravi and Jas keep V101's keys; Ravi, Priya Sandhu and Priya Natarajan keep their codes (V101, V191).

-- Profile fields a sign-in shows (like V101 did for the business personas), where the seed left them empty.
UPDATE identity.users
   SET first_name = coalesce(first_name, split_part(display_name, ' ', 1)),
       last_name = coalesce(last_name, substr(display_name, length(split_part(display_name, ' ', 1)) + 2)),
       phone_verified_at = coalesce(phone_verified_at, created_at),
       terms_version = coalesce(terms_version, '3.0'),
       terms_accepted_at = coalesce(terms_accepted_at, created_at)
 WHERE id IN ('01J9ZD3V00000000000000RAV1', '01J9ZD3V000000000000000JAS', '01J9ZD3V00000000000000PR1Y', '01J9ZD3V0000000000000C0001', '01J9ZD3V0000000000000C0002', '01J9ZD3V0000000000000C0003', '01J9ZD3V0000000000000C0004', '01J9ZD3V0000000000000C0005', '01J9ZD3V0000000000000C0006', '01J9ZD3V0000000000000C0007', '01J9ZD3V0000000000000C0008', '01J9ZD3V0000000000000C0009', '01J9ZD3V0000000000000C00K0', '01J9ZD3V00000000000000KF01', '01J9ZD3V00000000000000KM01', '01J9ZD3V00000000000000KM02', '01J9ZD3V00000000000000CP01', '01J9ZD3V00000000000000CS01', '01J9ZD3V00000000000000PNA1', '01J9ZD3V00000000000000MRC1');

